/// <summary>
/// Extension of table ProdBOM
/// </summary>
[ExtensionOf(tableStr(ProdBOM))]
final class AVAProdBOMDbt_Extension
{
}

Method.Source:
/// <summary>
/// Finds the first ProdBOM record for a provided ProdId with a transfer invent location
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <returns>ProdBOM</returns>
public static ProdBOM avaFindProdIdTransfer(ProdId _prodId)
{
    ProdBOM avaProdBOM;
    InventDim avaInventDim;
    InventLocation avaInventLocation;
    ProdTable avaProdTable = ProdTable::find(_prodId);

    select firstonly avaProdBOM
        join avaInventDim
        join avaInventLocation
        where avaInventLocation.InventLocationId == avaInventDim.InventLocationId
        && avaInventLocation.AVAPOTransfer == NoYes::Yes
        && avaInventDim.InventLocationId != avaProdTable.inventDim().InventLocationId
        && avaInventDim.InventDimId == avaProdBOM.InventDimId
        && avaProdBOM.ProdId == _prodId;

    return avaProdBOM;
}
